const lv_image_dsc_t *main_menu_icon_native(int tile, bool glyph, int size) {
	if (tile < 0 || tile >= 6) {
		return NULL;
	}
	if (glyph) {
		if (size >= 1 && size <= 47) {
			return &glyph_icons[size - 1][tile];
		}
	} else {
		if (size == 74) {
			return &color_icons[0][tile];
		}
	}
	return NULL;
}
